/** Official assembled Client consumes exact JSON packets generated by isolated real-PG Host tests. */
import { execFile } from 'node:child_process'
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'
import { expect } from 'vitest'
import { z } from 'zod'
import { SessionId } from '@deepseek-ai/dsh-session/types'
import { createClientTest, webApp } from '@deepseek-ai/dsh-client-test-runtime/src/assembly/index.ts'
import type { ISessions } from '@deepseek-ai/dsh-api-session-controller/client'
import { ok } from '@deepseek-ai/dsh-remote-mock'

const run = promisify(execFile)
const root = fileURLToPath(new URL('../../../../', import.meta.url))
const it = createClientTest({ roster: webApp.closure(['@deepseek-ai/dsh-api-session-controller']) })
const packet = z.object({ kind: z.literal('next'), frames: z.array(z.json()) }).loose()
const fixture = z.object({ sessionId: z.uuid().transform(SessionId), eventType: z.string(), snapshot: z.json(),
  next: packet, following: packet }).strict()

it.for(['attempt', 'message', 'interrupted'] as const)(
  'official Client consumes the %s settlement cut and later genuine end without duplicate rows or rebaseline',
  { timeout: 60_000 },
  async (kind, { mock, start }) => {
    const directory = await mkdtemp(join(tmpdir(), 'pe-employee7-client-cut-'))
    try {
      const config = process.env['PE_EMPLOYEE7_VITEST_CONFIG'] ?? join(root, 'vitest.power-evolve.cloud.config.ts')
      const { stdout, stderr } = await run(process.execPath, [join(root, 'node_modules/vitest/vitest.mjs'), 'run', '--config', config,
        'products/power-evolve/application/tests/employee7-native-assistant-read.spec.ts', '--testNamePattern',
        `^${kind} settlement cut hides`, '--reporter=json', `--outputFile=${join(directory, 'pg.json')}`],
      { cwd: root, env: { ...process.env, PE_EMPLOYEE7_CLIENT_FIXTURES_DIR: directory }, maxBuffer: 1_048_576, timeout: 30_000 })
      const report = z.object({ numPassedTests: z.number(), numFailedTests: z.number() }).loose()
        .parse(JSON.parse(await readFile(join(directory, 'pg.json'), 'utf8')))
      expect(report).toMatchObject({ numPassedTests: 1, numFailedTests: 0 })
      const raw = await readFile(join(directory, `${kind}.json`), 'utf8'), value = fixture.parse(JSON.parse(raw))
      const evidence = process.env['PE_EMPLOYEE7_CLIENT_EVIDENCE_DIR']
      if (evidence !== undefined) {
        await writeFile(join(evidence, `${kind}.json`), raw)
        await writeFile(join(evidence, `${kind}-pg.json`), await readFile(join(directory, 'pg.json')))
        await writeFile(join(evidence, `${kind}-pg.log`), stdout + stderr)
      }
      mock.remote.session.list.mockResolvedValue(ok({ items: [{ sessionId: value.sessionId, updatedAt: 1,
        agentAvailable: true, running: true, blank: false }] }))
      mock.stream('session/follow', (_args, stream) => { stream.push(value.snapshot) })
      const client = await start()
      const sessions: ISessions = client.ctx.sessions
      using reference = sessions.retain(value.sessionId, { source: 'controllerOperation' })
      const binding = await reference.ready
      expect(binding.eventSource.getSnapshot().entries.filter(entry => entry.type === 'transient')).toEqual([])
      const openingEntries = binding.eventSource.getSnapshot().entries
      for (const frame of value.next.frames) mock.streams.push('session/follow', frame)
      await mock.streams.drained('session/follow'); await client.flush()
      expect(mock.log.streams('session/follow')).toHaveLength(1)
      expect(binding.eventSource.getSnapshot().entries).toEqual(openingEntries)
      expect(binding.session.getSnapshot().openState).toBe('open')
      for (const frame of value.following.frames) mock.streams.push('session/follow', frame)
      await mock.streams.drained('session/follow'); await client.flush()
      expect(mock.log.streams('session/follow')).toHaveLength(1)
      expect(binding.eventSource.getSnapshot().entries.filter(entry => entry.type === 'transient')).toEqual([])
      expect(binding.eventSource.getSnapshot().entries.filter(entry => entry.event.type === value.eventType)).toHaveLength(1)
    } finally { await rm(directory, { recursive: true, force: true }) }
  })
